style.css:
body {
    background: url('https://i.imgur.com/qIxh2eT.jpg') !important; /* Cursed cringe background */
    background-size: cover !important;
    font-family: 'Comic Sans MS', cursive !important; /* Painful font */
}

h1, h2, h3, p, span, a {
    color: #ff0000 !important; /* Blood red text */
    font-size: 30px !important; /* Make everything too big */
    text-shadow: 3px 3px 10px yellow !important; /* Glowing text */
}

button {
    background: url('https://i.imgur.com/BQzaXfT.jpg') !important; /* Ugly meme button */
    color: lime !important;
    font-size: 25px !important;
    border: 5px dashed blue !important;
    transform: rotate(15deg) !important;
}

button:hover {
    transform: rotate(-15deg) scale(1.2) !important; /* Wobbly buttons */
}
